    if(parts.reduce((s,o)=>s+o.count,0)!==element.z||parts.some(o=>o.l>=o.n||o.count<1||o.count>2*(2*o.l+1))||new Set(parts.map(o=>o.key)).size!==parts.length)throw new Error('Invalid electron configuration');
    return parts;
