    for(let i=1;i<=bins;i++){const r=i*step,value=r*r*radialAmplitude(n,l,r)**2;cdf[i]=cdf[i-1]+(previous+value)*step/2;previous=value;}
    const integral=cdf[bins];for(let i=0;i<=bins;i++)cdf[i]/=integral;
