// A projected 3D probability point cloud. Rotation changes the camera only.
function createElectronCloudView(canvas,options){
  const ctx=canvas.getContext('2d');if(!ctx)return null;
  const colors=[...new Set(['#73bdff','#65f2d4','#c6a1ff','#ffd382',...ElectronCloudCore.palette])],listeners=[];
  let yaw=-.55,pitch=.25,zoom=1,auto=false,frame=0,last=0,dead=false,drag=null,cloud=options.cloud;
  const listen=(target,event,handler,extra)=>{target.addEventListener(event,handler,extra);listeners.push(()=>target.removeEventListener(event,handler,extra));};
  const sprites=colors.map(color=>{const c=document.createElement('canvas');c.width=c.height=24;const s=c.getContext('2d'),g=s.createRadialGradient(12,12,0,12,12,12);g.addColorStop(0,color);g.addColorStop(.23,color+'c0');g.addColorStop(.6,color+'38');g.addColorStop(1,color+'00');s.fillStyle=g;s.fillRect(0,0,24,24);return c;});
  function draw(){
    if(dead)return;
    ctx.clearRect(0,0,840,840);ctx.save();ctx.scale(2,2);
    const bg=ctx.createRadialGradient(210,195,4,210,210,280);bg.addColorStop(0,'#102f51');bg.addColorStop(1,'#06182e');ctx.fillStyle=bg;ctx.fillRect(0,0,420,420);
    const origin=ElectronCloudCore.project({x:0,y:0,z:0},yaw,pitch,zoom);
    ctx.font='11px system-ui';ctx.lineWidth=.7;
    for(const [name,p,color] of [['x',{x:1.08,y:0,z:0},'#ffb578'],['y',{x:0,y:1.08,z:0},'#c6a1ff'],['z',{x:0,y:0,z:1.08},'#65f2d4']]){
      const tip=ElectronCloudCore.project(p,yaw,pitch,zoom),tail=ElectronCloudCore.project({x:-p.x,y:-p.y,z:-p.z},yaw,pitch,zoom);ctx.strokeStyle=color+'60';ctx.beginPath();ctx.moveTo(tail.x,tail.y);ctx.lineTo(tip.x,tip.y);ctx.stroke();ctx.fillStyle=color;ctx.textAlign='left';ctx.fillText('+'+name,Math.min(393,Math.max(8,tip.x+5)),Math.min(380,Math.max(40,tip.y-4)));ctx.fillText('−'+name,Math.min(393,Math.max(8,tail.x+5)),Math.min(380,Math.max(40,tail.y-4)));
    }
    const geometry=cloud.kind==='hybrid'&&cloud.showGeometry&&cloud.model,vertices=geometry?geometry.directions.map(v=>ElectronCloudCore.project({x:v.x*.63,y:v.y*.63,z:v.z*.63},yaw,pitch,zoom)):[];
    if(geometry){ctx.save();ctx.lineWidth=.8;ctx.strokeStyle='#bddced5a';ctx.setLineDash([3,4]);for(const [a,b] of geometry.edges){ctx.beginPath();ctx.moveTo(vertices[a].x,vertices[a].y);ctx.lineTo(vertices[b].x,vertices[b].y);ctx.stroke();}for(let i=0;i<vertices.length;i++){if(!cloud.components.some(o=>o.hybrid&&o.id===geometry.hybrids[i].id))continue;const v=vertices[i];ctx.strokeStyle=geometry.hybrids[i].color+'a0';ctx.beginPath();ctx.moveTo(origin.x,origin.y);ctx.lineTo(v.x,v.y);ctx.stroke();}ctx.restore();}
    const plotted=cloud.points.map(p=>({...ElectronCloudCore.project(p,yaw,pitch,zoom),l:p.l,color:p.color})).sort((a,b)=>a.z-b.z);
    ctx.globalCompositeOperation='lighter';
    for(const p of plotted){if(p.x<0||p.x>420||p.y<0||p.y>420)continue;const size=4.4*p.perspective;ctx.globalAlpha=.22*Math.sqrt(4800/cloud.points.length);ctx.drawImage(sprites[p.color?colors.indexOf(p.color):p.l]||sprites[0],p.x-size/2,p.y-size/2,size,size);}
    ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;
    if(geometry){ctx.font='9px system-ui';ctx.textAlign='center';for(let i=0;i<vertices.length;i++){if(!cloud.components.some(o=>o.hybrid&&o.id===geometry.hybrids[i].id))continue;const v=vertices[i];ctx.fillStyle=geometry.hybrids[i].color;ctx.beginPath();ctx.arc(v.x,v.y,3,0,Math.PI*2);ctx.fill();ctx.fillText(String(i+1),v.x+8,v.y-6);}ctx.fillStyle='#bbd0e4';ctx.fillText(geometry.geometry+' · '+geometry.angles,210,378,380);}
    const glow=ctx.createRadialGradient(210,210,0,210,210,18);glow.addColorStop(0,'#ffdfc6');glow.addColorStop(.18,'#ff907c');glow.addColorStop(.45,'#ff89735c');glow.addColorStop(1,'#ff897300');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(210,210,18,0,Math.PI*2);ctx.fill();
    const title=cloud.kind==='hybrid'||cloud.key==='sp'?cloud.title:options.symbol+' · '+(cloud.key==='all'?'đám mây tổng':cloud.components?(cloud.components.length>3?cloud.components.length+' AO cùng hiển thị':cloud.title):cloud.key+' · '+cloud.orbital.label);
    ctx.fillStyle='#dcecff';ctx.font='10px system-ui';ctx.textAlign='center';ctx.fillText(title,210,23,382);ctx.fillStyle='#8aa5c3';ctx.font='9px system-ui';ctx.fillText(cloud.kind==='hybrid'||cloud.key==='sp'?'Bộ hàm minh họa · không phải mật độ của phân tử thực':'Hạt nhân phóng đại · kích thước quy ước',210,401,382);ctx.restore();
    const tally={};for(const p of cloud.points)tally[p.component]=(tally[p.component]||0)+1;
    canvas.dataset.yaw=yaw.toFixed(3);canvas.dataset.pitch=pitch.toFixed(3);canvas.dataset.zoom=zoom.toFixed(2);canvas.dataset.samples=cloud.points.length;canvas.dataset.subshell=cloud.key;canvas.dataset.direction=cloud.direction;canvas.dataset.components=cloud.components?.map(o=>o.id).join(',')||'';canvas.dataset.componentCounts=JSON.stringify(cloud.components?.map(o=>({id:o.id,count:tally[o.id]||0}))||[]);canvas.dataset.hybridType=cloud.type||'';canvas.dataset.geometry=cloud.model?.geometry||'';canvas.dataset.showGeometry=String(!!cloud.showGeometry);canvas.dataset.rendered='true';
    options.onView?.({yaw,pitch,zoom,auto});
  }
  function tick(time){frame=0;if(dead||!auto||document.hidden)return;const delta=last?Math.min(time-last,60):0;last=time;yaw+=delta*.00013;draw();frame=requestAnimationFrame(tick);}
  function setAuto(value){auto=!!value;last=0;cancelAnimationFrame(frame);frame=0;canvas.dataset.auto=String(auto);if(auto&&!document.hidden)frame=requestAnimationFrame(tick);options.onView?.({yaw,pitch,zoom,auto});}
  function redraw(){cancelAnimationFrame(frame);frame=0;draw();last=0;if(auto&&!document.hidden)frame=requestAnimationFrame(tick);}
  function setZoom(value){zoom=Math.max(.7,Math.min(1.6,value));redraw();}
  listen(canvas,'pointerdown',e=>{if(e.button!==0)return;setAuto(false);drag={x:e.clientX,y:e.clientY,yaw,pitch};canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});});
  listen(canvas,'pointermove',e=>{if(!drag)return;yaw=drag.yaw+(e.clientX-drag.x)*.012;pitch=Math.max(-1.45,Math.min(1.45,drag.pitch+(e.clientY-drag.y)*.012));redraw();});
  for(const type of ['pointerup','pointercancel','lostpointercapture'])listen(canvas,type,()=>{drag=null;});
  listen(canvas,'keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','=','Home'].includes(e.key))return;e.preventDefault();setAuto(false);if(e.key==='ArrowLeft')yaw-=.16;if(e.key==='ArrowRight')yaw+=.16;if(e.key==='ArrowUp')pitch=Math.min(1.45,pitch+.16);if(e.key==='ArrowDown')pitch=Math.max(-1.45,pitch-.16);if(e.key==='+'||e.key==='=')zoom=Math.min(1.6,zoom+.1);if(e.key==='-')zoom=Math.max(.7,zoom-.1);if(e.key==='Home'){yaw=-.55;pitch=.25;zoom=1;}redraw();});
  listen(canvas,'wheel',e=>{if(document.activeElement!==canvas)return;e.preventDefault();setZoom(zoom-e.deltaY*.001);},{passive:false});
  listen(document,'visibilitychange',()=>{cancelAnimationFrame(frame);frame=0;last=0;if(auto&&!document.hidden)frame=requestAnimationFrame(tick);});
  draw();canvas.dataset.auto='false';
  return {update(next){cloud=next;redraw();},geometry(show){cloud.showGeometry=!!show;redraw();},zoom:setZoom,toggle(){setAuto(!auto);},front(){setAuto(false);yaw=0;pitch=0;redraw();},axis(axis){setAuto(false);yaw=axis==='x'?Math.PI/2:0;pitch=axis==='z'?Math.PI/2:0;redraw();},reset(){setAuto(false);yaw=-.55;pitch=.25;zoom=1;redraw();},destroy(){dead=true;auto=false;cancelAnimationFrame(frame);listeners.forEach(fn=>fn());}};
}

  // Pure teaching calculations. Formula parsing is shared with the molecule workshop.
const ChemLabCore=(()=>{
  function create(parseFormula,data){
    const masses={H:1,Li:7,C:12,N:14,O:16,F:19,Na:23,Mg:24,Al:27,Si:28,P:31,S:32,Cl:35.5,K:39,Ca:40,Mn:55,Fe:56,Cu:64,Zn:65,Br:80,Ag:108,Sn:119,Ba:137,Pb:207,Au:197};
    const gcd=(a,b)=>b?gcd(b,a%b):a;
    const number=text=>{const s=String(text).trim();return /^\d+(?:[.,]\d{1,3})?$/.test(s)?Number(s.replace(',','.')):null;};
    function formula(f){const p=parseFormula(f,Object.keys(masses));if(!p)throw new Error('Invalid formula: '+f);return p.counts;}
    function totals(parts,coeffs){
      if(parts.length!==coeffs.length||coeffs.some(x=>!Number.isInteger(x)||x<1||x>9))throw new Error('Invalid coefficient');
      const counts={};parts.forEach((f,i)=>{for(const [s,n] of Object.entries(formula(f)))counts[s]=(counts[s]||0)+n*coeffs[i];});
      return counts;
    }
    function equation(reaction,coeffs){
      const n=reaction.left.length,left=totals(reaction.left,coeffs.slice(0,n)),right=totals(reaction.right,coeffs.slice(n)),symbols=[...new Set([...Object.keys(left),...Object.keys(right)])],balanced=symbols.every(s=>left[s]===right[s]),divisor=coeffs.reduce(gcd);
      const mass=a=>Object.entries(a).reduce((sum,[s,n])=>sum+masses[s]*n,0);
      return {left,right,symbols,balanced,divisor,primitive:balanced&&divisor===1,leftMass:mass(left),rightMass:mass(right)};
    }
    function atomMap(left,right){
      const bins={};right.forEach((a,i)=>(bins[a.symbol]??=[]).push(i));
      const result=left.map((a,i)=>{const j=bins[a.symbol]?.shift();if(j===undefined)throw new Error('Atom mismatch');return {id:i,symbol:a.symbol,from:a,to:right[j]};});
      if(Object.values(bins).some(b=>b.length))throw new Error('Extra atoms');return result;
    }
    function valence(task,a,b){
      if(![a,b].every(x=>Number.isInteger(x)&&x>=0&&x<=8))throw new Error('Invalid atom count');
      const left=a*task.va,right=b*task.vb,divisor=gcd(a,b),positive=a>0&&b>0,balanced=positive&&left===right;
      const least=task.va*task.vb/gcd(task.va,task.vb),minimum=[least/task.va,least/task.vb];
      const units={[task.a]:a,[task.b]:b},counts={};
      for(const [unit,multiple] of Object.entries(units))for(const [sym,n] of Object.entries(formula(unit)))counts[sym]=(counts[sym]||0)+n*multiple;
      const f=task.order.map(s=>{const n=units[s],group=Object.values(formula(s)).reduce((a,b)=>a+b,0)>1;return (group&&n>1?'('+s+')':s)+(n===1?'':n);}).join('');
      return {left,right,balanced,primitive:balanced&&divisor===1,minimum,formula:positive?f:'?',counts};
    }
    function solution(s){
      if(!data.solutes[s.salt]||!data.solutes[s.salt].solubility[String(s.temp)]||![s.water,s.solute].every(Number.isFinite)||s.water<0||s.water>900||s.solute<0||s.solute>300)throw new Error('Invalid solution state');
      const limit=data.solutes[s.salt].solubility[String(s.temp)]*s.water/100,dissolved=Math.min(s.solute,limit),solid=Math.max(0,s.solute-dissolved),mass=s.water+dissolved,percent=mass>0?100*dissolved/mass:null;
      return {...s,limit,dissolved,solid,mass,percent,total:s.water+s.solute,saturated:s.water>0&&s.solute>0&&s.solute>=limit-1e-9};
    }
    function solutionMove(current,action,amount){
      if(!Number.isFinite(amount)||amount<=0)return {accepted:false,reason:'Số lượng phải lớn hơn 0.'};
      const s=solution(current),next={water:s.water,solute:s.solute,salt:s.salt,temp:s.temp};
      if(action==='water')next.water+=amount;
      else if(action==='solute')next.solute+=amount;
      else if(action==='evaporate'){if(amount>s.water+1e-9)return {accepted:false,reason:'Lượng nước đang có không đủ để bay hơi.'};next.water=Math.max(0,next.water-amount);}
      else if(action==='drain'){
        if(s.mass===0||amount>s.mass+1e-9)return {accepted:false,reason:'Không đủ dung dịch để lấy ra; không lấy kèm chất rắn dư.'};
        const share=Math.min(1,amount/s.mass);next.water*=1-share;next.solute=Math.max(0,next.solute-s.dissolved*share);
      }else return {accepted:false,reason:'Thao tác không hợp lệ.'};
      if(next.water>900+1e-8||next.solute>300+1e-8)return {accepted:false,reason:'Vượt sức chứa mô hình: tối đa 900 g nước và 300 g chất tan đã thêm.'};
      return {accepted:true,state:next};
    }
    function solutionPolicy(task,current,next,action){
      if(!task)return true;
      if(next.salt!==task.initial.salt||next.temp!==task.initial.temp)return false;
      const close=(a,b)=>Math.abs(a-b)<1e-7;
      if(task.policy==='dilute')return close(next.solute,task.initial.solute)&&next.water>=task.initial.water;
      if(task.policy==='evaporate')return close(next.solute,task.initial.solute)&&next.water<=task.initial.water;
      if(task.policy==='saturation')return close(next.water,task.initial.water);
      if(task.policy==='drain')return action==='drain';
      return true;
    }
    function solutionGoal(task,s,answer){
      const result=solution(s),target=Object.entries(task.goal).every(([key,value])=>result[key]!==null&&Math.abs(result[key]-value)<.015);
      const answerOK=task.answer===undefined||answer!==null&&Math.abs(answer-task.answer)<.051;
      return {correct:target&&answerOK,target,answerOK,result};
    }
    return {gcd,number,formula,totals,equation,atomMap,valence,solution,solutionMove,solutionPolicy,solutionGoal,masses};
  }
  return {create};
})();

// Pure computations used by the added teaching panels, independent of browser state.
const ChemExtensionCore=(()=>{
  const ve={H:1,Li:1,C:4,N:5,O:6,F:7,Na:1,Mg:2,Al:3,Cl:7,K:1,Ca:2};
  const z={H:1,Li:3,C:6,N:7,O:8,F:9,Na:11,Mg:12,Al:13,Cl:17,K:19,Ca:20};
  const key=(a,b)=>[a,b].sort((a,b)=>a-b).join('-');
  function bondState(t,links={}){
    const spent=t.atoms.map(()=>0),gain=t.atoms.map(()=>0);let shared=0;
    for(const [k,n] of Object.entries(links)){
      const [a,b]=k.split('-').map(Number);if(!Number.isInteger(n)||n<0||a===b||!t.atoms[a]||!t.atoms[b])throw Error('Invalid electron move');
      if(t.type==='ionic'){spent[a]+=n;gain[b]+=n;}else{spent[a]+=n;spent[b]+=n;shared+=2*n;}
    }
    const atoms=t.atoms.map((s,i)=>({symbol:s,protons:z[s],electrons:t.type==='ionic'?z[s]-spent[i]+gain[i]:z[s],valence:ve[s],lone:ve[s]-spent[i],charge:t.type==='ionic'?spent[i]-gain[i]:0,shell:t.type==='ionic'?ve[s]-spent[i]+gain[i]:ve[s]+spent[i]}));
    const valid=atoms.every((a,i)=>a.lone>=0&&(t.type!=='ionic'||(t.charges[i]>0?gain[i]===0&&spent[i]<=t.charges[i]:spent[i]===0&&gain[i]<=-t.charges[i])));
    const complete=t.type==='ionic'?valid&&atoms.every((a,i)=>a.charge===t.charges[i]):valid&&t.bonds.every(([a,b,n])=>(links[key(a,b)]||0)===n)&&Object.keys(links).every(k=>t.bonds.some(([a,b])=>key(a,b)===k))&&atoms.every(a=>a.shell===(a.symbol==='H'?2:8));
    return {atoms,valid,complete,totalElectrons:atoms.reduce((a,b)=>a+b.electrons,0),valenceElectrons:t.atoms.reduce((a,s)=>a+ve[s],0),shared};
  }
  function moveElectron(t,links,a,b,delta=1){
    if(a===b||!t.atoms[a]||!t.atoms[b])return {accepted:false,reason:'Chọn hai nguyên tử khác nhau.'};
    if(t.type==='ionic'&&(t.charges[a]<=0||t.charges[b]>=0))return {accepted:false,reason:'Trong mẫu này electron chuyển từ nguyên tử kim loại sang nguyên tử phi kim.'};
    const k=t.type==='ionic'?a+'-'+b:key(a,b),next={...links,[k]:(links[k]||0)+delta};
    if(next[k]<0)return {accepted:false,reason:'Không có electron hoặc cặp electron ở nối này để trả lại.'};if(next[k]===0)delete next[k];
    const result=bondState(t,next);
    if(!result.valid||t.type==='covalent'&&result.atoms.some(x=>x.shell>(x.symbol==='H'?2:8)))return {accepted:false,reason:'Không đủ electron hóa trị hoặc vượt số electron lớp ngoài trong mô hình đã chọn.'};
    return {accepted:true,links:next,result};
  }
  const kw=1e-14;
  function acidH(c,k=0){
    if(!k)return (c+Math.sqrt(c*c+4*kw))/2;
    let lo=1e-16,hi=Math.max(1,c+1);for(let i=0;i<150;i++){const h=(lo+hi)/2;if(h-kw/h-c*k/(k+h)>0)hi=h;else lo=h;}return (lo+hi)/2;
  }
  function ph(sample,c,dilution=1){
    if(!sample||!Number.isFinite(c)||c<0||c>.1||!Number.isFinite(dilution)||dilution<1)throw Error('Invalid pH state');
    c/=dilution;let h=1e-7;
    if(sample.kind==='acid'||sample.kind==='weakAcid')h=acidH(c,sample.k);
    if(sample.kind==='base'||sample.kind==='weakBase')h=kw/acidH(c,sample.k);
    const value=-Math.log10(h);return {ph:value,h,oh:kw/h,c,classification:Math.abs(value-7)<1e-5?'neutral':value<7?'acid':'base'};
  }
  function neutralize(baseMl){
    if(!Number.isFinite(baseMl)||baseMl<0||baseMl>200)throw Error('Invalid volume');
    const acidMol=.01,baseMol=baseMl*.0001,volume=(100+baseMl)/1000,excess=acidMol-baseMol,c=Math.abs(excess)/volume;
    const h=excess>=0?acidH(c):kw/acidH(c);return {ph:-Math.log10(h),h,oh:kw/h,acidMol,baseMol,volume,saltMol:Math.min(acidMol,baseMol),remaining:Math.abs(excess),classification:Math.abs(excess)<1e-12?'neutral':excess>0?'acid':'base'};
  }
  function indicator(ph,id){
    if(id==='litmus')return ph<4.5?{color:'#e87588',name:'Đỏ'}:ph>8.3?{color:'#719cec',name:'Xanh'}:{color:'#a68bc4',name:'Tím / vùng chuyển màu'};
    if(id==='phenol')return ph<8.2?{color:'#e5f4fa',name:'Không màu'}:ph>12?{color:'#f8b8db',name:'Hồng; có thể nhạt dần trong kiềm rất mạnh'}:{color:'#ef6dac',name:ph<10?'Hồng nhạt → hồng':'Hồng'};
    const colors=['#e94b59','#ed694c','#ef923f','#e8b63e','#c8c34a','#9ac85a','#65b88c','#46b3ac','#439ebd','#5287ca','#7271cb','#9666bf','#ab5caf','#bb56a2','#c64c96'];return {color:colors[Math.max(0,Math.min(14,Math.round(ph)))],name:'Màu tham khảo; khoảng pH '+Math.max(0,Math.floor(ph)-1)+'–'+Math.min(14,Math.ceil(ph)+1)};
  }
  // A colour can support several environments; a correct guess is not proof.
  function phEvidence(value,id){
    const all=['acid','neutral','base'];
    if(id==='meter')return {id,possible:[Math.abs(value-7)<1e-5?'neutral':value<7?'acid':'base'],text:'Máy pH (mô hình): '+value.toFixed(2)};
    const result=indicator(value,id);let possible=all;
    if(id==='litmus')possible=value<4.5?['acid']:value>8.3?['base']:all;
    if(id==='phenol')possible=value>=8.2?['base']:all;
    if(id==='universal'){const lo=Math.max(0,Math.floor(value)-1),hi=Math.min(14,Math.ceil(value)+1);possible=hi<7?['acid']:lo>7?['base']:all;}
    return {id,possible,text:({litmus:'Giấy quỳ tím',phenol:'Phenolphthalein',universal:'Chỉ thị vạn năng'}[id]||id)+': '+result.name};
  }
  function evidenceConclusion(evidence=[]){return ['acid','neutral','base'].filter(c=>evidence.every(e=>e.possible.includes(c)));}
  function stoich(r,amounts){
    const n=r.left.length;if(amounts.length!==n||amounts.some(x=>!Number.isFinite(x)||x<0))throw Error('Invalid mol amount');
    const ratios=amounts.map((x,i)=>x/r.answer[i]),extent=Math.min(...ratios),used=amounts.map((_,i)=>extent*r.answer[i]);return {extent,used,left:amounts.map((x,i)=>Math.max(0,x-used[i])),products:r.answer.slice(n).map(x=>extent*x),limiting:ratios.map((x,i)=>Math.abs(x-extent)<1e-8?i:-1).filter(i=>i>=0)};
  }
  function molarity(mass,molarMass,volumeMl){if(![mass,molarMass,volumeMl].every(Number.isFinite)||mass<0||mass>100||molarMass<=0||volumeMl<50||volumeMl>2000)throw Error('Invalid concentration');return {mol:mass/molarMass,volume:volumeMl/1000,concentration:mass/molarMass/(volumeMl/1000)};}
  const order=['K','Na','Ca','Mg','Al','Zn','Fe','Sn','Pb','H','Cu','Ag','Au'];
  function metal(data,symbol,reagentId,clean=false){
    const m=data.metals.find(x=>x.symbol===symbol),r=data.metalReagents.find(x=>x.id===reagentId);if(!m||!r)throw Error('Unknown case');
    const base={id:symbol+'_'+reagentId,classification:'no',gas:false,deposit:false,condition:'Nhiệt độ thường, dung dịch loãng; hình ảnh và thời gian chỉ minh họa.',equation:null,observation:'Không có biến đổi rõ trong điều kiện đang xét.',explanation:'Cần xét cả vị trí trong dãy, môi trường và bề mặt kim loại.',color:r.color};
    const yes=(equation,observation,explanation,extra={})=>({...base,classification:'yes',equation,observation,explanation,...extra});
    const cond=(observation,explanation,extra={})=>({...base,classification:'condition',observation,explanation,...extra});
    const lcm=(a,b)=>{let x=a;while(x%b)x+=a;return x;};
    const salt=(s,v,anion,av)=>{const l=lcm(v,av),a=l/v,b=l/av;return s+(a===1?'':a)+(!(/^[A-Z][a-z]?$/.test(anion))&&b>1?'('+anion+')':anion)+(b===1?'':b);};
    const eq=(left,right,answer)=>({left,right,answer});
    if(reagentId==='water'){
      if(['K','Na','Ca'].includes(symbol)){const v=m.valence,L=lcm(v,2),hydroxide=salt(symbol,v,'OH',1);return yes(eq([symbol,'H2O'],[hydroxide,'H2'],[L/v,L,L/v,L/2]),symbol==='Ca'?'Có bọt hydrogen; calcium hydroxide có thể làm nước vẩn đục.':'Có bọt hydrogen; kim loại phản ứng mạnh với nước.','Kim loại nhường electron, nước tham gia tạo hydroxide và hydrogen.',{gas:true});}
      if(symbol==='Mg')return cond('Phản ứng với nước lạnh rất chậm, có thể chưa thấy rõ trong thời gian ngắn.','Magnesium phản ứng rõ hơn với nước nóng hoặc hơi nước; không coi không thấy ngay là hoàn toàn không phản ứng.');
      if(symbol==='Al')return cond('Màng oxide bảo vệ khiến aluminium khó phản ứng rõ với nước lạnh.','Bề mặt và điều kiện quyết định hiện tượng; không chỉ suy từ thứ tự hoạt động.');
      return {...base,explanation:'Không quan sát phản ứng rõ với nước lạnh trong mẫu; khác với hơi nước ở nhiệt độ cao hoặc sự ăn mòn kéo dài.'};
    }
    if(reagentId==='steam'){
      if(symbol==='Mg'||symbol==='Zn')return yes(eq([symbol,'H2O'],[symbol+'O','H2'],[1,1,1,1]),'Ở nhiệt độ cao, tạo oxide và hydrogen.','Hơi nước và nước lạnh là hai điều kiện khác nhau.',{gas:true,condition:'Đun nóng kim loại trong dòng hơi nước; không phải nước lạnh.'});
      if(symbol==='Fe')return yes(eq(['Fe','H2O'],['Fe3O4','H2'],[3,4,1,4]),'Sắt nung nóng tác dụng hơi nước, tạo Fe3O4 và hydrogen.','Sản phẩm oxide được chọn là Fe3O4 trong điều kiện của mẫu.',{gas:true,condition:'Sắt nung đỏ, cho hơi nước đi qua.'});
      if(['K','Na','Ca','Al'].includes(symbol))return cond('Cần xét điều kiện riêng; bộ mẫu không mô phỏng định lượng trường hợp này.','K, Na, Ca đã phản ứng với nước lạnh; aluminium có màng oxide. Không gán cùng một quy tắc cho mọi kim loại.',{assessed:false});
      return cond('Trường hợp này chưa được mô phỏng với nhiệt độ và điều kiện đủ cụ thể.','Không dùng việc thiếu dữ liệu của mô hình để kết luận kim loại không phản ứng với hơi nước.',{assessed:false,condition:'Cần dữ kiện nhiệt độ và bề mặt cụ thể; ngoài các mẫu hơi nước Mg, Zn, Fe đang được định nghĩa.'});
    }
    if(r.target&&['K','Na','Ca'].includes(symbol))return cond('Kim loại có thể phản ứng mạnh với môi trường nước trước; không dùng mô hình đẩy kim loại đơn giản.','Trong dung dịch muối có nước, có thể sinh hydrogen và hydroxide, kéo theo kết tủa. Không kết luận trực tiếp thu kim loại từ muối chỉ nhờ đứng trước trong dãy.',{gas:true});
    if(symbol==='Al'&&!clean)return cond('Màng oxide có thể làm phản ứng chậm khởi đầu hoặc khó quan sát.','Chọn bề mặt đã xử lí để xét phản ứng lý tưởng sau khi bỏ ảnh hưởng màng oxide.');
    if(reagentId==='HCl'){
      if(symbol==='Pb')return cond('Phản ứng ban đầu chậm; lớp PbCl2 ít tan có thể cản trở phản ứng tiếp tục.','Lead đứng trước H nhưng lớp muối ít tan làm thay đổi hiện tượng. Mô hình không dự đoán tốc độ từ dãy hoạt động.');
      if(order.indexOf(symbol)>order.indexOf('H'))return {...base,explanation:'Kim loại đứng sau H không giải phóng hydrogen từ HCl loãng. Quy tắc này không áp dụng cho mọi acid như HNO3.'};
      const v=m.valence,L=lcm(v,2);return yes(eq([symbol,'HCl'],[salt(symbol,v,'Cl',1),'H2'],[L/v,L,L/v,L/2]),'Kim loại tan dần, xuất hiện bọt khí hydrogen.','Kim loại đứng trước H, xét HCl loãng và bề mặt thích hợp.',{gas:true});
    }
    if(order.indexOf(symbol)>=order.indexOf(r.target))return {...base,explanation:'Kim loại này không đẩy được ion kim loại đang chọn theo phản ứng thế của bộ mẫu.'};
    if(symbol==='Pb'&&reagentId==='CuSO4')return cond('Có thể hình thành lớp PbSO4 khó tan trên bề mặt, cản trở phản ứng tiếp tục.','Không mô phỏng phản ứng thế đến hoàn toàn khi sản phẩm tạo màng khó tan.');
    if(reagentId==='AgNO3'&&['Fe','Sn'].includes(symbol))return cond('Có thể tạo silver; trạng thái oxi hóa của kim loại còn phụ thuộc lượng Ag+ và điều kiện.','Không tự gán một sản phẩm Fe(II) hoặc Sn(II) duy nhất cho mọi lượng silver nitrate. Đây là trường hợp mở rộng.',{deposit:true});
    const tv=reagentId==='AgNO3'?1:2,av=reagentId==='AgNO3'?1:2,anion=reagentId==='AgNO3'?'NO3':'SO4',v=m.valence,L=lcm(v,tv),product=salt(symbol,v,anion,av);
    return yes(eq([symbol,reagentId],[product,r.target],[L/v,L/tv,1,L/tv]),({Cu:'Copper đỏ nâu',Ag:'Silver xám sáng',Fe:'Iron xám',Zn:'Zinc xám'}[r.target])+' bám trên bề mặt; kim loại ban đầu tan dần.','Kim loại đứng trước kim loại trong muối và các điều kiện của phản ứng thế được đáp ứng.',{deposit:true,depositSymbol:r.target,color:symbol==='Cu'?'#86c7ed':symbol==='Fe'?'#cbe3cd':'#e3f2f5'});
  }
  return {ve,z,key,bondState,moveElectron,ph,neutralize,indicator,phEvidence,evidenceConclusion,stoich,molarity,order,metal};
})();

  /* Deterministic scoring. Essays are never graded by keyword matching. */
const ReviewCore=(()=>{
  function textbookQuestion(q){
  if(q.grade!=='9')return q;
  const text=x=>typeof x==='string'?x.replace(/Ethanol/g,'Ethylic alcohol').replace(/ethanol/g,'ethylic alcohol'):x;
  const out={...q,prompt:text(q.prompt),explanation:text(q.explanation)};
  if(q.options)out.options=q.options.map(text);
  if(q.statements)out.statements=q.statements.map(s=>({...s,text:text(s.text),explanation:text(s.explanation)}));
  if(q.rubric)out.rubric=q.rubric.map(r=>({...r,text:text(r.text)}));
  return out;
 }

 const labels={NB:'Nhận biết',TH:'Thông hiểu',VD:'Vận dụng',VDC:'Vận dụng cao'};
  function numeric(s){
    const t=String(s??'').trim().replace(/\u2212/g,'-').replace(',','.');
    if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(t))return null;
    const n=Number(t);return Number.isFinite(n)?n:null;
  }
  function complete(q,a){
    if(q.type==='tf')return q.statements.every((s,i)=>typeof a?.[i]==='boolean');
    if(q.type==='mc')return Number.isInteger(a)&&a>=0&&a<q.options.length;
    if(q.type==='number')return numeric(a)!==null;
    return typeof a==='string'&&a.trim().length>0;
  }
  function score(q,a){
    if(q.type==='essay')return {earned:0,max:0,correct:null};
    if(q.type==='tf'){
      const earned=q.statements.reduce((n,s,i)=>n+(typeof a?.[i]==='boolean'&&a[i]===s.answer?s.points:0),0);
      return {earned,max:q.points,correct:complete(q,a)&&earned===q.points};
    }
    const ok=q.type==='mc'?a===q.answer:numeric(a)!==null&&Math.abs(numeric(a)-q.answer)<=(q.tolerance??1e-8);
    return {earned:ok?q.points:0,max:q.points,correct:ok};
  }
  function totals(questions,answers={},self={}){
    let earned=0,max=0,essayMax=0,selfEarned=0,selfReviewed=0;const levels={NB:0,TH:0,VD:0,VDC:0},topics={};
    questions.forEach(q=>{
      if(q.type==='tf')q.statements.forEach(s=>levels[s.level]+=s.points);else levels[q.level]+=q.points;
      if(q.type==='essay'){
        essayMax+=q.points;
        if(self[q.id]?.reviewed){selfReviewed++;q.rubric.forEach((r,i)=>{if(self[q.id].criteria?.[i]===true)selfEarned+=r.points;});}
      }else{
        const s=score(q,answers[q.id]);earned+=s.earned;max+=s.max;
        topics[q.topic]??={earned:0,max:0};topics[q.topic].earned+=s.earned;topics[q.topic].max+=s.max;
      }
    });
    return {earned,max,essayMax,selfEarned,selfReviewed,levels,topics};
  }
  function expired(session,now=Date.now()){return session.mode==='exam'&&Number.isFinite(session.endAt)&&now>=session.endAt;}
  function missed(questions,answers){return questions.filter(q=>q.type!=='essay'&&!score(q,answers[q.id]).correct);}
  function validSession(s,version,questions){
    const ids=new Set(questions.map(q=>q.id));
    return !!s&&s.version===version&&['exam','practice'].includes(s.mode)&&['working','submitted'].includes(s.status)&&
      Array.isArray(s.ids)&&s.ids.length>0&&new Set(s.ids).size===s.ids.length&&s.ids.every(id=>ids.has(id))&&
      Number.isInteger(s.pos)&&s.pos>=0&&s.pos<s.ids.length&&s.answers&&typeof s.answers==='object'&&s.flags&&typeof s.flags==='object'&&
      (s.mode!=='exam'||Number.isFinite(s.endAt))&&s.revealed&&typeof s.revealed==='object'&&s.self&&typeof s.self==='object';
  }
  return {labels,numeric,complete,score,totals,expired,missed,validSession,textbookQuestion};
})();
if(typeof module!=='undefined'&&module.exports)module.exports=ReviewCore;

