 const alternate=(entry.link||[]).find(l=>l.rel==='alternate');if(!alternate)return null;
 let url;try{url=new URL(alternate.href,origin);if(url.host!==new URL(origin).host||url.username||url.password)return null;url.protocol=new URL(origin).protocol;}catch(e){return null;}
