 const title=String(entry.title?.$t||'Bài học'),match=/^Bài\s+(\d+)[.\s]/u.exec(title);
 if(match&&plain.startsWith('KẾT NỐI TRI THỨC VỚI CUỘC SỐNG')){plain=plain.replace(/^KẾT NỐI TRI THỨC VỚI CUỘC SỐNG\s*·\s*KHTN\s+\d+\s+Bài\s+\d+\s*·\s*/u,'');const heading=title.replace(/^Bài\s+\d+\.\s*/u,'').replace(/\s*\|.*$/u,'');if(plain.startsWith(heading))plain=plain.slice(heading.length).trim();}
