function reviewLoad(){try{const s=JSON.parse(localStorage.getItem(REVIEW_KEY)||'null'),valid=ReviewCore.validSession(s,REVIEW_BANK.version,REVIEW_BANK.questions)&&(s.source!=='bank'||[STUDY_BANK.version,...(STUDY_BANK.compatibleSessionVersions||[])].includes(s.bankVersion))&&(s.source!=='collection'||s.collectionVersion===SOURCE_COLLECTION.version);reviewOutdated=!!s&&!valid;return valid?s:null;}catch(e){return null;}}
function reviewUpdateNote(){return reviewOutdated?'<p class="rv-pending" role="status">Ngân hàng đã được sửa nội dung. Hãy bắt đầu bài mới để dùng câu hỏi và đáp án hiện hành.</p>':'';}
function reviewSave(){if(!state.reviewSession)return;reviewOutdated=false;try{localStorage.setItem(REVIEW_KEY,JSON.stringify(state.reviewSession));}catch(e){reviewStorageOK=false;}}
function reviewQuestions(){const a=state.reviewSession;return a.ids.map(id=>ReviewCore.textbookQuestion(StudyBankCore.weighted(REVIEW_BY_ID[id],a.weights?.[id])));}
function reviewDate(s){return new Date(s).toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'});}
function reviewUnits(g,term,kind){
  const p=REVIEW_PLAN.grades[g];if(!p)return [];
  if(term==='year')return p.lessons.map(l=>({lesson:l,partial:false}));
  const scope=p.scopes[term+'-'+kind];
  return (scope?.lessons||[]).map(s=>({lesson:p.lessons.find(l=>l.id===s.lesson),partial:s.partial,hasUnspecifiedWeek:s.hasUnspecifiedWeek}));
}
function reviewOpen(){
  cleanup();state.game='review-setup';
  state.reviewSetup??={grade:['6','7','8','9'].includes(state.hubGrade)?state.hubGrade:'7',term:'hki',kind:'end',mode:'practice',topic:'all',variant:'0'};
  if(!state.reviewSession)state.reviewSession=reviewLoad();
  reviewSetupRender();
}
function reviewSetupRender(){
  state.game='review-setup';const s=state.reviewSetup,p=REVIEW_PLAN.grades[s.grade],available=s.grade==='7'&&s.term==='hki';
  const scopeKey=s.term==='year'?'year':s.term+'-'+s.kind,randomReady=StudyBankCore.readiness(bankScopePool(s.grade,scopeKey)).ready;
  const units=reviewUnits(s.grade,s.term,s.kind),saved=state.reviewSession,topicKeys=Object.keys(REVIEW_BANK.topics).filter(k=>!k.startsWith('bank-')&&(s.kind!=='mid'||k!=='periodic'));
  if(!topicKeys.includes(s.topic))s.topic='all';
  const options=(arr,value)=>arr.map(([id,label])=>'<option value="'+id+'"'+(value===id?' selected':'')+'>'+label+'</option>').join('');
  render('<div class="hh60g-stage rv-stage">'+topbar('<span>Kết nối tri thức</span>')+'<div class="hh60g-body rv-body"><div class="rv-intro">'+companionArt('study','hh60g-sample-character')+'<span class="rv-kicker">ĐỀ MẪU MINH HỌA · LỚP 7 HKI</span>'+heading('Ôn luyện & Kiểm tra')+'<p>4 đề mẫu lớp 7 HKI dùng minh họa ma trận. Với bài học dở trong PPCT, giáo viên đối chiếu phần thực tế đã dạy trước khi dùng.</p><div class="rv-ratio"><span>Nhận biết <b>40%</b></span><span>Thông hiểu <b>30%</b></span><span>Vận dụng <b>20%</b></span><span>Vận dụng cao <b>10%</b></span></div><div class="rv-bottom"><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="bank-open">Ngân hàng câu hỏi & bài tập</button></div></div>'+
    '<div class="rv-label">1. Chọn lớp</div><div class="rv-grades" aria-label="Lớp học">'+['6','7','8','9','10','11','12'].map(g=>'<button type="button" data-rv-grade="'+g+'" aria-pressed="'+(s.grade===g)+'">Lớp '+g+(g==='7'?'<small>Có đề HKI</small>':'')+'</button>').join('')+'</div>'+
    '<div class="rv-selects"><label>2. Học kỳ<select id="rv-term">'+options([['hki','Học kỳ I'],['hkii','Học kỳ II'],['year','Cả năm']],s.term)+'</select></label><label>3. Mốc ôn tập<select id="rv-kind"'+(s.term==='year'?' disabled':'')+'>'+options([['mid','Giữa kỳ'],['end','Cuối kỳ']],s.kind)+'</select></label><label>4. Hình thức<select id="rv-mode">'+options([['practice','Ôn luyện · có giải thích'],['exam','Làm đề · có thời gian']],s.mode)+'</select></label></div>'+
    '<section class="rv-scope"><div class="rv-scope-heading"><h4>'+(p?'Phạm vi từ kế hoạch dạy học':'Chưa có kế hoạch dạy học')+'</h4><span>'+(p?'2026–2027':'Lớp '+s.grade)+'</span></div>'+
    (p?'<p class="rv-small">'+(s.term==='year'?'Toàn bộ phần Hóa và bài mở đầu được phân công trong năm.':'Đến trước tuần '+(p.tests[s.term+'-'+s.kind]?.week||'?')+' theo mốc kiểm tra KHTN. Phạm vi HKII gồm cả phần nối tiếp sau mốc cuối HKI.')+'</p><ul>'+units.map(({lesson:l,partial,hasUnspecifiedWeek})=>'<li><strong>Bài '+l.number+'.</strong> '+esc(l.title)+(partial?'<span class="rv-tag">Học một phần trước mốc</span>':'')+(hasUnspecifiedWeek?'<span class="rv-tag">Có tiết chưa ghi tuần</span>':'')+'</li>').join('')+'</ul><p class="rv-small">Bài học dở và tiết cùng tuần kiểm tra cần đối chiếu nội dung đã dạy. Đây là phần Hóa và phương pháp học KHTN; không phải toàn bộ đề KHTN.</p>':'<p>Hóa học '+s.grade+' đã có ngân hàng theo chủ đề. Chưa có PPCT của trường cho mốc học kỳ; chọn Cả năm để tạo đề luyện hoặc mở ngân hàng để chọn chủ đề.</p>')+'</section>'+
    (available?'<div class="rv-start-panel"><div><h4>'+(s.mode==='exam'?'Đề luyện theo ma trận':'Ôn lại trước khi làm đề')+'</h4><p>'+(s.mode==='exam'?'21 câu · 45 phút luyện tập · 10 điểm. Gồm nhiều lựa chọn, đúng–sai, trả lời số và tự luận.':'Không bấm giờ. Có kiến thức tóm tắt, lời giải sau khi thử và đường mở mô phỏng liên quan.')+'</p></div><label>Mã đề<select id="rv-variant">'+options([['0','Mã A'],['1','Mã B']],s.variant)+'</select></label>'+(s.mode==='practice'?'<label>Chủ đề<select id="rv-topic"><option value="all">Tất cả chủ đề</option>'+topicKeys.map(k=>'<option value="'+k+'"'+(s.topic===k?' selected':'')+'>'+REVIEW_BANK.topics[k].name+'</option>').join('')+'</select></label>':'')+'<button type="button" class="hh60g-btn" data-rv-action="start">'+(saved?.status==='working'?'Làm bài mới · thay bài tạm':s.mode==='exam'?'Bắt đầu làm đề':'Bắt đầu ôn luyện')+'</button></div>':'<div class="rv-pending"><strong>'+(randomReady?'Ngân hàng trong phạm vi này đã có thể tạo đề mới.':'Chưa mở ra đề theo mốc học kỳ chưa có PPCT.')+'</strong><p>Đề mẫu A/B hiện có: Lớp 7 → Học kỳ I. Các lớp có thể dùng ngân hàng và nút ra đề ngẫu nhiên phía dưới.</p></div>')+bankRandomPanel(s.grade,scopeKey)+
    (saved?'<section class="rv-saved"><div><strong>'+(saved.status==='working'?'Có bài đang làm':'Kết quả gần nhất')+'</strong><p>'+esc(saved.title)+' · '+reviewDate(saved.startedAt)+'</p></div><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="resume">'+(saved.status==='working'?'Tiếp tục bài đã lưu':'Xem kết quả')+'</button></section>':reviewUpdateNote())+
    '<details class="rv-guide"><summary>Ma trận, cách chấm và nguồn đối chiếu</summary><p><b>Mức độ theo điểm:</b> 4 điểm Nhận biết; 3 điểm Thông hiểu; 2 điểm Vận dụng; 1 điểm Vận dụng cao. Trong mẫu ba mức, gộp hai mức cuối thành 3 điểm Vận dụng.</p><p><b>Dạng câu:</b> 12 câu nhiều lựa chọn × 0,25 = 3 điểm; 2 câu đúng–sai, mỗi câu 4 ý × 0,25 = 2 điểm; 4 câu trả lời số × 0,5 = 2 điểm; 3 câu tự luận = 3 điểm. Đúng–sai chấm từng ý, cộng tuyến tính.</p><p><b>Kết quả:</b> hệ thống chấm 7 điểm khách quan. Tự luận hiện đáp án và tiêu chí sau khi nộp để đối chiếu; điểm tự đánh giá có nhãn riêng. Đây là khu luyện tập, không dùng để thi có giám sát.</p><p>Bản đặc tả được biên soạn theo phạm vi từng đề. Mẫu tham khảo lấy từ <a href="'+esc(REVIEW_PLAN.references[0].url)+'" target="_blank" rel="noopener">phụ lục Công văn 7991</a>; nội dung đối chiếu với chương trình KHTN và <a href="'+esc(REVIEW_PLAN.references[1].url)+'" target="_blank" rel="noopener">SGV của NXB Giáo dục</a>. Không có một bản đặc tả dùng nguyên trạng cho mọi kỳ học. Việc chọn dạng đề ở đây là cấu hình luyện tập; không khẳng định áp dụng bắt buộc cho mọi trường THCS.</p></details><p class="rv-small">Bài tạm và kết quả lưu trên trình duyệt này; không đồng bộ giữa các máy. Khi xóa dữ liệu trình duyệt có thể mất bài đã lưu.</p></div></div>');
}
function reviewStart(modeOverride,idsOverride){
  const s=state.reviewSetup,paper=REVIEW_BANK.papers.find(p=>p.grade===s.grade&&p.term===s.term&&p.kind===s.kind&&p.id.endsWith('-'+s.variant));
  if(!paper)return;
  let ids=idsOverride||paper.ids.slice();const mode=modeOverride||s.mode;
  if(!idsOverride&&mode==='practice'&&s.topic!=='all')ids=ids.filter(id=>REVIEW_BY_ID[id].topic===s.topic);
  if(!ids.length)return;
  const orders={};ids.forEach(id=>{const q=REVIEW_BY_ID[id];if(q.type==='mc')orders[id]=shuffle(q.options.map((_,i)=>i));});
  state.reviewSession={version:REVIEW_BANK.version,paper:paper.id,title:paper.title+' · '+paper.code,mode,ids,orders,answers:{},flags:{},revealed:{},self:{},pos:0,status:'working',startedAt:Date.now(),endAt:mode==='exam'?Date.now()+paper.durationMinutes*60000:null};
  reviewSave();reviewRun();
}
function reviewRun(){
  cleanup();const a=state.reviewSession;if(!a)return reviewOpen();
  if(a.status==='submitted'){reviewResult();return;}
  if(ReviewCore.expired(a)){reviewSubmit(true);return;}
  state.game='review-run';reviewQuestionRender();
  if(a.mode==='exam'){state.timer=setInterval(reviewTick,1000);reviewTick();}
}
function reviewTick(){
  const a=state.reviewSession;if(state.game!=='review-run'||!a||a.mode!=='exam'||a.status!=='working')return;
  const ms=a.endAt-Date.now();if(ms<=0){reviewSubmit(true);return;}
  const target=view.querySelector('#rv-clock');if(target){const sec=Math.ceil(ms/1000);target.textContent=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');target.classList.toggle('rv-clock-low',sec<=300);}
}
function reviewAnswered(q,a){return ReviewCore.complete(q,a);}
function reviewKnowledge(q){
  const t=REVIEW_BANK.topics[q.topic];return '<details class="rv-knowledge"><summary>Kiến thức cần nhớ · '+esc(t.name)+'</summary><ul>'+t.knowledge.map(k=>'<li>'+esc(k)+'</li>').join('')+'</ul><p><b>Dễ nhầm:</b> '+esc(t.pitfall)+'</p>'+(t.simulation?'<button type="button" class="hh60g-btn hh60g-secondary" data-study-go="'+t.simulation+'">Mở mô phỏng để ôn</button>':'')+'</details>';
}
function reviewAnswerUI(q,a,locked){
  const dis=locked?' disabled':'';
  if(q.type==='mc')return '<fieldset class="rv-choices"><legend class="hh60g-sr">Chọn một đáp án</legend>'+(state.reviewSession.orders?.[q.id]||q.options.map((_,i)=>i)).map((i,j)=>'<label class="rv-choice'+(a===i?' rv-selected':'')+'"><input type="radio" name="rv-answer" data-rv-mc="'+i+'"'+(a===i?' checked':'')+dis+'/><span class="rv-letter">'+String.fromCharCode(65+j)+'</span><span>'+esc(q.options[i])+'</span></label>').join('')+'</fieldset>';
  if(q.type==='tf')return '<div class="rv-tf">'+q.statements.map((s,i)=>'<fieldset><legend>'+String.fromCharCode(97+i)+') '+esc(s.text)+'</legend>'+[true,false].map(b=>'<label><input type="radio" name="rv-tf-'+i+'" data-rv-tf="'+i+'" value="'+b+'"'+(a?.[i]===b?' checked':'')+dis+'/>'+(b?'Đúng':'Sai')+'</label>').join('')+'</fieldset>').join('')+'</div><p class="rv-small">Mỗi ý đúng được 0,25 điểm; các ý chấm độc lập.</p>';
  if(q.type==='number')return '<label class="rv-number-label">Câu trả lời bằng số<input id="rv-number" type="text" inputmode="decimal" autocomplete="off" value="'+esc(a??'')+'" placeholder="Ví dụ: 12 hoặc 12,5"'+dis+'/></label><p class="rv-small">Chỉ nhập số; chấp nhận dấu phẩy hoặc dấu chấm thập phân.</p>';
  return '<label class="rv-essay-label">Bài làm của em<textarea id="rv-essay" rows="6" maxlength="12000" placeholder="Trình bày cách nghĩ và giải thích bằng dữ liệu trong đề…"'+dis+'>'+esc(a??'')+'</textarea></label><p class="rv-small">Tự luận có đáp án và thang điểm sau khi nộp. Hệ thống không chấm theo từ khóa.</p>';
}
function reviewSolution(q,a,withRubric=false){
  let text='';
  if(q.type==='mc')text='<p><b>Đáp án:</b> '+esc(q.options[q.answer])+'</p>';
  if(q.type==='number')text='<p><b>Đáp án:</b> '+numberText(q.answer)+'</p>';
  if(q.type==='tf')text='<ul>'+q.statements.map((s,i)=>'<li><b>'+String.fromCharCode(97+i)+') '+(s.answer?'Đúng':'Sai')+'.</b> '+esc(s.explanation)+'</li>').join('')+'</ul>';
  text+='<p class="rv-solution-text">'+esc(q.explanation||'')+'</p>';
  if(state.reviewSession?.source==='collection')text+='<p class="rv-small">Nguồn: '+esc(state.reviewSession.sourceNotes?.[q.id]||q.sourceLocation||'Chuyên đề đã gửi')+'</p>';
  else if(q.sourceDocument)text+='<p class="rv-small">Nguồn: '+esc(q.sourceDocument)+' · '+esc(q.sourceLocation)+'</p>';
  if(q.sourceUrl)text+='<p class="rv-small">Tham khảo dạng bài: <a href="'+esc(q.sourceUrl)+'" target="_blank" rel="noopener">'+esc(q.sourceTitle)+'</a>. Câu đã được biên soạn lại.</p>';
  if(q.type==='essay')text+='<ul>'+q.rubric.map((r,i)=>'<li>'+esc(r.text)+' <b>('+numberText(r.points)+' điểm)</b></li>').join('')+'</ul>';
  return text;
}
function reviewQuestionRender(){
  const a=state.reviewSession,qs=reviewQuestions(),q=qs[a.pos],ans=a.answers[q.id],revealed=a.mode==='practice'&&a.revealed[q.id];
  const answered=qs.filter(x=>reviewAnswered(x,a.answers[x.id])).length;
  const types={mc:'Chọn một đáp án',tf:'Đúng hoặc sai',number:'Trả lời ngắn',essay:'Tự luận'};
  render('<div class="hh60g-stage rv-stage'+(a.mode==='exam'?' rv-exam-mode':'')+'">'+topbar('<span>'+(a.mode==='exam'?'Làm đề':'Ôn luyện')+'</span>')+'<div class="hh60g-body rv-body">'+learningJourney(1)+'<div class="rv-run-head"><div><p class="rv-kicker">'+esc(a.title)+'</p>'+heading('Câu '+(a.pos+1)+' / '+qs.length)+'</div>'+(a.mode==='exam'?'<div class="rv-clock" aria-label="Thời gian còn lại" id="rv-clock">…</div>':'<span class="rv-tag">Không bấm giờ</span>')+'</div><div class="rv-progress"><span id="rv-progress">Đã làm '+answered+'/'+qs.length+'</span><span id="rv-storage">'+(reviewStorageOK?'Tự lưu bài trên thiết bị':'Trình duyệt không cho lưu bài')+'</span></div><progress aria-label="Tiến độ làm bài" value="'+answered+'" max="'+qs.length+'"></progress>'+companionNote(a.mode==='exam'?'Đọc kĩ đề, ghi lại cách làm và rà soát trước khi nộp bài.':'Thử trả lời trước, rồi mở lời giải để đối chiếu cách nghĩ của em.','study',a.mode==='exam')+(a.generated?bankMatrixMarkup(qs):'')+'<div class="rv-layout"><nav class="rv-question-nav" aria-label="Đi tới câu hỏi">'+qs.map((x,i)=>'<button type="button" data-rv-jump="'+i+'" class="'+(i===a.pos?'rv-current ':'')+(reviewAnswered(x,a.answers[x.id])?'rv-done ':'')+(a.flags[x.id]?'rv-flagged':'')+'" aria-label="Câu '+(i+1)+(reviewAnswered(x,a.answers[x.id])?', đã trả lời':'')+(a.flags[x.id]?', đã đánh dấu':'')+'"'+(i===a.pos?' aria-current="step"':'')+'>'+(i+1)+'</button>').join('')+'</nav><section class="rv-question"><div class="rv-question-meta"><span>'+types[q.type]+' · '+numberText(q.points)+' điểm</span><button type="button" data-rv-action="flag" aria-pressed="'+!!a.flags[q.id]+'">'+(a.flags[q.id]?'★ Đã đánh dấu':'☆ Xem lại sau')+'</button></div><p class="rv-prompt">'+esc(q.prompt)+'</p>'+(q.assumptions?'<p class="rv-assumptions">'+esc(q.assumptions)+'</p>':'')+reviewAnswerUI(q,ans,revealed)+
    (revealed?'<div class="rv-feedback" role="status">'+companionFeedback(q.type!=='essay'&&ReviewCore.score(q,ans).correct)+(q.type==='essay'?'<strong>Đối chiếu cách lập luận của em</strong>':'<strong>'+ (ReviewCore.score(q,ans).correct?'Đúng rồi.':'Cùng xem lại lời giải.')+'</strong>')+reviewSolution(q,ans)+'</div>':'')+
    (a.mode==='practice'?'<div class="rv-practice-actions"><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="check"'+(revealed?' disabled':'')+'>Xem lời giải sau khi thử</button><span class="rv-inline-message" id="rv-inline-message" role="status"></span></div>'+reviewKnowledge(q):'')+
    '<div class="rv-question-actions"><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="prev"'+(!a.pos?' disabled':'')+'>← Câu trước</button>'+(a.pos<qs.length-1?'<button type="button" class="hh60g-btn" data-rv-action="next">Câu tiếp →</button>':'<button type="button" class="hh60g-btn" data-rv-action="finish">Rà soát và nộp bài</button>')+'</div></section></div><div class="rv-bottom"><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="setup">Lưu và về khu ôn tập</button><button type="button" class="hh60g-btn" data-rv-action="finish">'+(a.mode==='exam'?'Nộp bài':'Kết thúc lượt ôn')+'</button></div></div></div>',false);
  if(a.mode==='exam')reviewTick();
}
function reviewStoreAnswer(answer){
  const a=state.reviewSession;if(a?.status!=='working')return;
  if(ReviewCore.expired(a)){reviewSubmit(true);return;}
  const q=reviewQuestions()[a.pos];if(a.revealed[q.id])return;
  a.answers[q.id]=answer;reviewSave();
  const qs=reviewQuestions(),count=qs.filter(x=>reviewAnswered(x,a.answers[x.id])).length;
  const p=view.querySelector('#rv-progress');if(p)p.textContent='Đã làm '+count+'/'+qs.length;
  const progress=view.querySelector('progress');if(progress)progress.value=count;
  const b=view.querySelector('[data-rv-jump="'+a.pos+'"]');if(b)b.classList.toggle('rv-done',reviewAnswered(q,answer));
  const storage=view.querySelector('#rv-storage');if(storage&&!reviewStorageOK)storage.textContent='Trình duyệt không cho lưu bài';
  view.querySelectorAll('.rv-choice').forEach(el=>el.classList.toggle('rv-selected',!!el.querySelector('input:checked')));
}
function reviewConfirm(){
  if(ReviewCore.expired(state.reviewSession)){reviewSubmit(true);return;}
  const a=state.reviewSession,qs=reviewQuestions(),left=qs.filter(q=>!reviewAnswered(q,a.answers[q.id])).length,flags=Object.values(a.flags).filter(Boolean).length;
  const old=view.querySelector('.rv-submit-dialog');if(old)old.remove();
  const d=document.createElement('dialog');d.className='rv-submit-dialog';
  d.innerHTML='<h3>Nộp bài và xem kết quả?</h3><p>'+ (left?'Còn '+left+' câu chưa trả lời đủ.':'Em đã trả lời đủ các câu.')+' Có '+flags+' câu được đánh dấu xem lại.</p><p>Sau khi nộp, câu trả lời được khóa. Tự luận có thang điểm để đối chiếu.</p><div class="rv-bottom"><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="cancel-submit">Quay lại làm bài</button><button type="button" class="hh60g-btn" data-rv-action="submit">Nộp bài</button></div>';
  view.appendChild(d);d.showModal();
}
function reviewSubmit(expired=false){
  const a=state.reviewSession;if(!a)return;
  a.status='submitted';a.submittedAt=Date.now();a.timedOut=expired;reviewSave();reviewResult();
}
function reviewExportMarkup(){
 const p=state.reviewSession.exportProfile||{};
 return '<section class="rv-export"><div><h4>Tải bài làm</h4><p>Gồm câu hỏi, câu trả lời đã nộp, điểm và nhận xét ôn tập.</p></div><div class="rv-export-fields"><label>Họ và tên <span>(không bắt buộc)</span><input id="rv-export-name" type="text" maxlength="120" autocomplete="name" value="'+esc(p.name||'')+'" placeholder="Họ và tên học sinh"/></label><label>Lớp <span>(không bắt buộc)</span><input id="rv-export-class" type="text" maxlength="60" value="'+esc(p.className||'')+'" placeholder="Ví dụ: 8A1"/></label></div><label class="rv-export-solutions"><input id="rv-export-solutions" type="checkbox"'+(p.solutions?' checked':'')+'/>Kèm đáp án, lời giải và thang chấm</label><div class="rv-export-buttons"><button type="button" class="hh60g-btn" data-rv-action="export-pdf">Tải PDF</button><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="export-word">Tải Word (.docx)</button></div><p id="rv-export-status" class="rv-small" role="status" aria-live="polite">Thông tin chỉ dùng trên trình duyệt này.</p></section>';
}
function reviewScoreMarkup(t,essays,selfDone){
 return '<div class="rv-score-grid">'+(t.max>0?'<div><small>Phần chấm tự động</small><strong>'+numberText(t.earned)+' <span>/ '+numberText(t.max)+'</span></strong><p>Chấm theo đáp án đã công bố.</p></div>':'')+(essays.length?'<div><small>Phần tự luận</small><strong id="rv-self-score">'+(selfDone?numberText(t.selfEarned)+' <span>/ '+numberText(t.essayMax)+'</span>':numberText(t.essayMax)+' <span>điểm cần đối chiếu</span>')+'</strong><p>Điểm tự đánh giá; giáo viên có thể chấm lại.</p></div>':'')+'</div>';
}
function reviewResult(){
  cleanup();state.game='review-result';const a=state.reviewSession,qs=reviewQuestions(),t=ReviewCore.totals(qs,a.answers,a.self),missed=ReviewCore.missed(qs,a.answers),essays=qs.filter(q=>q.type==='essay');
  const selfDone=t.selfReviewed===essays.length,weak=Object.entries(t.topics).filter(([_,s])=>s.earned<s.max).sort((a,b)=>(a[1].earned/a[1].max)-(b[1].earned/b[1].max));
  const qlist=qs.map((q,i)=>{const score=ReviewCore.score(q,a.answers[q.id]);let given;
    if(q.type==='mc')given=Number.isInteger(a.answers[q.id])?q.options[a.answers[q.id]]:'Chưa trả lời';
    else if(q.type==='tf')given=q.statements.map((s,j)=>String.fromCharCode(97+j)+') '+(typeof a.answers[q.id]?.[j]==='boolean'?(a.answers[q.id][j]?'Đúng':'Sai'):'Chưa chọn')).join('; ');
    else given=String(a.answers[q.id]??'').trim()||'Chưa trả lời';
    return '<details class="rv-review-item"><summary><span>Câu '+(i+1)+' · '+esc(REVIEW_BANK.topics[q.topic].name)+'</span><b>'+(q.type==='essay'?'Tự luận':numberText(score.earned)+'/'+numberText(q.points)+' điểm')+'</b></summary><p class="rv-prompt">'+esc(q.prompt)+'</p><p class="rv-given"><b>Bài làm đã nộp:</b> '+esc(given)+'</p>'+reviewSolution(q,a.answers[q.id])+ (q.type==='essay'?'<fieldset class="rv-rubric"><legend>Tự đối chiếu bài làm · điểm tham khảo</legend>'+q.rubric.map((r,j)=>'<label><input type="checkbox" data-rv-rubric="'+q.id+'" data-rv-criterion="'+j+'"'+(a.self[q.id]?.criteria?.[j]?' checked':'')+'/>'+esc(r.text)+' ('+numberText(r.points)+' điểm)</label>').join('')+'<label class="rv-reviewed"><input type="checkbox" data-rv-reviewed="'+q.id+'"'+(a.self[q.id]?.reviewed?' checked':'')+'/>Tôi đã đọc đủ thang điểm và đối chiếu câu này</label></fieldset>':'')+'</details>';
  }).join('');
  render('<div class="hh60g-stage rv-stage">'+topbar('<span>Kết quả luyện tập</span>')+'<div class="hh60g-body rv-body">'+learningScene({title:a.timedOut?'Đã nộp khi hết giờ':'Kết quả bài làm',kicker:a.title,description:'Cùng xem lại từng câu, đọc lời giải và chọn phần cần ôn tiếp. Tự luận có thang điểm để đối chiếu bài làm.',pose:'celebrate',tone:'teal'})+learningJourney(2)+reviewScoreMarkup(t,essays,selfDone)+'<p id="rv-total" class="rv-total">'+(!essays.length?'Điểm phần khách quan: '+numberText(t.earned)+' / '+numberText(t.max)+' điểm.':selfDone?'Tổng tham khảo có tự đánh giá: '+numberText(t.earned+t.selfEarned)+' / '+numberText(t.max+t.essayMax)+' điểm.':'Chưa có tổng điểm toàn bài vì còn phần tự luận chưa đối chiếu.')+'</p>'+(a.mode==='practice'?'<p class="rv-small">Lượt ôn có thể đã mở lời giải; kết quả dùng để theo dõi luyện tập.</p>':'')+
    reviewExportMarkup()+(weak.length?'<details class="rv-next rv-guide"><summary>Nên ôn lại phần nào?</summary>'+weak.map(([k,s])=>'<div><strong>'+esc(REVIEW_BANK.topics[k].name)+'</strong><span>'+numberText(s.earned)+'/'+numberText(s.max)+' điểm khách quan</span><p>'+esc(REVIEW_BANK.topics[k].pitfall)+'</p>'+(REVIEW_BANK.topics[k].simulation?'<button type="button" class="hh60g-btn hh60g-secondary" data-study-go="'+REVIEW_BANK.topics[k].simulation+'">Mở mô phỏng liên quan</button>':'')+'</div>').join('')+'</details>':t.max>0?'<p>Em đã trả lời đúng toàn bộ câu khách quan trong lượt này.'+(essays.length?' Hãy tiếp tục đối chiếu phần tự luận.':'')+'</p>':'<p>Đọc đáp án và thang chấm ở từng câu để tự đối chiếu bài làm.</p>')+
    '<div class="rv-bottom">'+(missed.length?'<button type="button" class="hh60g-btn" data-rv-action="retry">Luyện lại '+missed.length+' câu khách quan chưa đúng đủ</button>':'')+'<button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="setup">'+'Chọn bài mới'+'</button></div>'+(a.generated?bankMatrixMarkup(qs):'')+'<h4>Đáp án và lời giải từng câu</h4>'+qlist+'<p class="rv-small">Thang điểm này phục vụ tự học; chưa phải kết quả kiểm tra do nhà trường xác nhận.</p></div></div>');
}
function reviewRefreshSelf(){
  const a=state.reviewSession,t=ReviewCore.totals(reviewQuestions(),a.answers,a.self),essays=reviewQuestions().filter(q=>q.type==='essay'),done=t.selfReviewed===essays.length;
  const el=view.querySelector('#rv-self-score');if(el)el.innerHTML=done?numberText(t.selfEarned)+' <span>/ '+numberText(t.essayMax)+'</span>':numberText(t.essayMax)+' <span>điểm cần đối chiếu</span>';
  const total=view.querySelector('#rv-total');if(total)total.textContent=done?'Tổng tham khảo có tự đánh giá: '+numberText(t.earned+t.selfEarned)+' / '+numberText(t.max+t.essayMax)+' điểm.':'Chưa có tổng điểm toàn bài vì còn phần tự luận chưa đối chiếu.';
}
function reviewExport(format){
 const a=state.reviewSession;if(a?.status!=='submitted')return;
 const status=view.querySelector('#rv-export-status');
 try{
  const m=ReviewExportCore.model(a,reviewQuestions(),REVIEW_BANK.topics,a.exportProfile||{}),pdf=format==='pdf';
  const bytes=pdf?ReviewExportCore.pdf(m):ReviewExportCore.docx(m),ext=pdf?'pdf':'docx';
  const url=URL.createObjectURL(new Blob([bytes],{type:pdf?'application/pdf':'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})),link=document.createElement('a');
  link.href=url;link.download=m.filename+'.'+ext;link.hidden=true;view.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
  if(status)status.textContent='Đã tạo file '+(pdf?'PDF':'Word')+'. Nếu chưa thấy, mở mục tải xuống của trình duyệt.';
 }catch(error){if(status)status.textContent='Chưa tạo được file. Hãy thử lại hoặc chọn định dạng còn lại.';}
}
view.addEventListener('click',event=>{
  const b=event.target.closest('button');if(!b||b.disabled)return;
  if(b.dataset.rvGrade){state.reviewSetup.grade=b.dataset.rvGrade;reviewSetupRender();return;}
  if(b.dataset.rvJump!==undefined&&state.game==='review-run'){
    if(ReviewCore.expired(state.reviewSession)){reviewSubmit(true);return;}
    const i=Number(b.dataset.rvJump);if(Number.isInteger(i)&&i>=0&&i<reviewQuestions().length){state.reviewSession.pos=i;reviewSave();reviewQuestionRender();}return;
  }
  const action=b.dataset.rvAction;if(!action)return;
  if(action==='start'){if(state.reviewSession?.status==='working'){
    const d=document.createElement('dialog');d.className='rv-submit-dialog';d.innerHTML='<h3>Thay bài đang lưu?</h3><p>Bài mới sẽ thay bài tạm hiện tại trên thiết bị này.</p><div class="rv-bottom"><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="cancel-submit">Giữ bài tạm</button><button type="button" class="hh60g-btn" data-rv-action="replace-start">Làm bài mới</button></div>';view.appendChild(d);d.showModal();
  }else reviewStart();return;}
  if(action==='replace-start'){view.querySelector('.rv-submit-dialog')?.close();reviewStart();return;}
  if(action==='resume'){reviewRun();return;}
  if(action==='setup'){cleanup();reviewSave();bankRestoreContext();bankOpen();return;}
  if(action==='bank-open'){state.bankSetup=bankDefault();bankOpen();return;}
  if(action==='exam-setup'){const b=state.bankSetup;state.reviewSetup={grade:b.grade,term:b.scope==='year'?'year':b.scope.split('-')[0],kind:b.scope==='year'?'end':b.scope.split('-')[1],mode:'exam',topic:'all',variant:'0'};reviewOpen();return;}
  if(action==='prev'||action==='next'){
    if(ReviewCore.expired(state.reviewSession)){reviewSubmit(true);return;}
    const a=state.reviewSession;a.pos=Math.max(0,Math.min(reviewQuestions().length-1,a.pos+(action==='next'?1:-1)));reviewSave();reviewQuestionRender();return;
  }
  if(action==='flag'){const a=state.reviewSession,q=reviewQuestions()[a.pos];a.flags[q.id]=!a.flags[q.id];reviewSave();reviewQuestionRender();return;}
  if(action==='check'){
    const a=state.reviewSession,q=reviewQuestions()[a.pos];
    if(!reviewAnswered(q,a.answers[q.id])){view.querySelector('#rv-inline-message').textContent='Hãy thử trả lời đủ trước khi xem lời giải.';return;}
    a.revealed[q.id]=true;reviewSave();reviewQuestionRender();return;
  }
  if(action==='finish'){reviewConfirm();return;}
  if(action==='cancel-submit'){view.querySelector('.rv-submit-dialog')?.close();view.querySelector('.rv-submit-dialog')?.remove();return;}
  if(action==='submit'){view.querySelector('.rv-submit-dialog')?.close();reviewSubmit();return;}
  if(action==='retry'){
    const a=state.reviewSession;if(a.source==='collection'||a.source==='bank'){bankRestoreContext(a);const missed=ReviewCore.missed(reviewQuestions(),a.answers).map(q=>q.id);bankRequestStart(missed);return;}const paper=REVIEW_BANK.papers.find(p=>p.id===a.paper);state.reviewSetup={grade:paper.grade,term:paper.term,kind:paper.kind,variant:paper.id.slice(-1),topic:'all',mode:'practice'};
    const missed=ReviewCore.missed(reviewQuestions(),a.answers).map(q=>q.id);reviewStart('practice',missed);return;
  }
  if(action==='export-pdf'||action==='export-word')reviewExport(action==='export-pdf'?'pdf':'word');
});
view.addEventListener('change',event=>{
  const el=event.target,s=state.reviewSetup;
  if(['rv-term','rv-kind','rv-mode','rv-topic','rv-variant'].includes(el.id)){
    s[el.id.slice(3)]=el.value;reviewSetupRender();return;
  }
  if(state.game==='review-run'){
    if(el.dataset.rvMc!==undefined)reviewStoreAnswer(Number(el.dataset.rvMc));
    if(el.dataset.rvTf!==undefined){const a=state.reviewSession,q=reviewQuestions()[a.pos],values={...(a.answers[q.id]||{})};values[Number(el.dataset.rvTf)]=el.value==='true';reviewStoreAnswer(values);}
  }
  if(state.game==='review-result'){
    if(el.id==='rv-export-solutions'){state.reviewSession.exportProfile??={};state.reviewSession.exportProfile.solutions=el.checked;reviewSave();return;}
    const id=el.dataset.rvRubric||el.dataset.rvReviewed;if(!id)return;const a=state.reviewSession,q=REVIEW_BY_ID[id];if(!q||q.type!=='essay')return;
    a.self[id]??={criteria:{},reviewed:false};if(el.dataset.rvReviewed)a.self[id].reviewed=el.checked;else a.self[id].criteria[Number(el.dataset.rvCriterion)]=el.checked;reviewSave();reviewRefreshSelf();
  }
});
view.addEventListener('input',event=>{if(state.game==='review-run'&&(event.target.id==='rv-number'||event.target.id==='rv-essay'))reviewStoreAnswer(event.target.value);if(state.game==='review-result'&&['rv-export-name','rv-export-class'].includes(event.target.id)){state.reviewSession.exportProfile??={};state.reviewSession.exportProfile[event.target.id==='rv-export-name'?'name':'className']=event.target.value;reviewSave();}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')reviewTick();});

/* The library uses the same saved-answer runner and rubric as the reviewed sample papers. */
const BANK_HISTORY_KEY='hh60_paper_history_'+STUDY_BANK.version;
const BANK_SCOPES=[['hki-mid','Giữa HKI'],['hki-end','Cuối HKI'],['hkii-mid','Giữa HKII'],['hkii-end','Cuối HKII'],['year','Cả năm']];
const BANK_TYPES={mc:'Trắc nghiệm A–D',tf:'Đúng–sai',number:'Trả lời số',essay:'Tự luận'};
function bankMatrixMarkup(qs){
 const rows={};qs.forEach(q=>{rows[q.topic]??={NB:0,TH:0,VD:0,VDC:0};if(q.type==='tf')q.statements.forEach(s=>rows[q.topic][s.level]+=s.points);else rows[q.topic][q.level]+=q.points;});
 const audit=StudyBankCore.audit(qs);
 return '<details class="rv-guide sb-matrix"><summary>Ma trận của đề này</summary><div class="sb-table-wrap"><table><caption>Phân bố điểm theo nội dung và mức độ</caption><thead><tr><th>Nội dung</th><th>Nhận biết</th><th>Thông hiểu</th><th>Vận dụng</th><th>VD cao</th></tr></thead><tbody>'+Object.entries(rows).map(([k,r])=>'<tr><th>'+esc(REVIEW_BANK.topics[k].name)+'</th>'+['NB','TH','VD','VDC'].map(l=>'<td>'+numberText(r[l])+'</td>').join('')+'</tr>').join('')+'<tr><th>Tổng điểm</th>'+['NB','TH','VD','VDC'].map(l=>'<td><b>'+numberText(audit.levels[l])+'</b></td>').join('')+'</tr></tbody></table></div><p>Đề luyện phần Hóa, 10 điểm. Hệ thống chấm 7 điểm khách quan; 3 điểm tự luận có thang chấm để đối chiếu.</p></details>';
}
function bankHistory(){try{const h=JSON.parse(localStorage.getItem(BANK_HISTORY_KEY)||'{}');return h&&typeof h==='object'&&!Array.isArray(h)?h:{};}catch(e){return {};}}
