function bankRequestStart(ids,generated=null){
 state.bankPendingStart={ids,generated};
 if(state.reviewSession?.status==='working'){
  const d=document.createElement('dialog');d.className='rv-submit-dialog';d.innerHTML='<h3>Thay bài đang lưu?</h3><p>Bài mới sẽ thay bài tạm hiện tại trên trình duyệt này.</p><div class="rv-bottom"><button type="button" class="hh60g-btn hh60g-secondary" data-rv-action="cancel-submit">Giữ bài tạm</button><button type="button" class="hh60g-btn" data-bank-action="confirm-start">Bắt đầu bài mới</button></div>';view.appendChild(d);d.showModal();
 }else bankStartPending();
}
function bankStartPending(){
 const pending=state.bankPendingStart;if(!pending)return;
 const d=view.querySelector('.rv-submit-dialog');if(d){d.close();d.remove();}
 const {ids,generated}=pending,qs=ids.map(id=>REVIEW_BY_ID[id]),orders={};
 qs.forEach(q=>{if(q.type==='mc')orders[q.id]=shuffle(q.options.map((_,i)=>i));});
 const grade=generated?.grade||qs[0].grade,scope=generated?.scope||state.bankSetup?.scope||'year',code=Date.now().toString(36).toUpperCase();
 state.reviewSession={version:REVIEW_BANK.version,bankVersion:STUDY_BANK.version,source:'bank',subject:qs[0].subject||'chemistry',sourceNotes:Object.fromEntries(ids.map(id=>[id,bankSourceNote(id)])),generated:!!generated,grade,scope,
  paper:'bank-'+grade+'-'+scope,title:(generated?'Đề ngẫu nhiên':'Luyện từ ngân hàng')+' · '+((qs[0].subject||'chemistry')==='biology'?'Sinh học ':'Hóa học ')+grade+' · '+(BANK_SCOPES.find(x=>x[0]===scope)?.[1]||'Cả năm')+' · '+code,
  mode:generated?'exam':'practice',ids,orders,weights:generated?.weights||{},answers:{},flags:{},revealed:{},self:{},pos:0,status:'working',startedAt:Date.now(),endAt:generated?Date.now()+45*60000:null};
 if(generated){
  const h=bankHistory(),key=grade+'|'+scope;h[key]??=[];h[key].push({ids,at:Date.now()});h[key]=h[key].slice(-8);
  try{localStorage.setItem(BANK_HISTORY_KEY,JSON.stringify(h));}catch(e){reviewStorageOK=false;}
 }
 state.bankPendingStart=null;reviewSave();reviewRun();
}
function bankPracticeStart(){
 const pool=bankFiltered(),key='hh60_bank_practice_recent_'+STUDY_BANK.version;let recent=[];
 try{recent=JSON.parse(localStorage.getItem(key)||'[]');}catch(e){}
 const rank=shuffle(pool).sort((a,b)=>Number(recent.includes(a.id))-Number(recent.includes(b.id))),chosen=[];
 for(const [type,count] of [['mc',4],['tf',2],['number',2],['essay',2]])chosen.push(...rank.filter(q=>q.type===type).slice(0,count));
 for(const q of rank){if(chosen.length>=Math.min(10,pool.length))break;if(!chosen.includes(q))chosen.push(q);}
 const ids=shuffle(chosen).map(q=>q.id);if(!ids.length)return;
 try{localStorage.setItem(key,JSON.stringify(ids));}catch(e){}
 bankRequestStart(ids);
}
function bankRestoreContext(a=state.reviewSession){
 if(!a)return;const q=REVIEW_BY_ID[a.ids[0]];
 state.bankSetup={...bankDefault(),mode:'practice',subject:a.subject||q?.subject||'chemistry',grade:a.grade||q?.grade||'7',scope:a.scope&&a.scope!=='all'?a.scope:'year'};
}
function bankGenerate(grade,scope){
 const key=grade+'|'+scope,result=StudyBankCore.generate(bankScopePool(grade,scope),bankHistory()[key]||[]);
 if(!result.ok){say('Chưa thể tạo bộ câu mới đúng cấu trúc trong phạm vi này.');return false;}
 const qs=result.ids.map(id=>StudyBankCore.weighted(REVIEW_BY_ID[id],result.weights[id]));
 if(!StudyBankCore.audit(qs).valid){say('Phạm vi này chưa đủ điều kiện để ra đề đúng ma trận.');return false;}
 bankRequestStart(result.ids,{grade,scope,weights:result.weights});return true;
}
view.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.bankSubject){state.bankSetup={...bankDefault(),subject:b.dataset.bankSubject,grade:b.dataset.bankSubject==='biology'?'7':state.bankSetup.grade,scope:'year'};bankRender();return;}
 if(b.dataset.bankGrade){state.bankSetup.grade=b.dataset.bankGrade;state.bankSetup.lesson=null;if(!REVIEW_PLAN.grades[b.dataset.bankGrade])state.bankSetup.scope='year';state.bankSetup.topic='all';state.bankSetup.page=0;bankRender();return;}
 if(b.dataset.bankMode){state.bankSetup.mode=b.dataset.bankMode;if(b.dataset.bankMode==='exam')state.bankSetup.lesson=null;bankRender();return;}
 if(b.dataset.bankOne){bankRequestStart([b.dataset.bankOne]);return;}
 if(b.dataset.bankRandom){const [g,s]=b.dataset.bankRandom.split('|');bankGenerate(g,s);return;}
 const a=b.dataset.bankAction;if(!a)return;
 if(a==='clear-lesson'){state.bankSetup.lesson=null;state.bankSetup.topic='all';state.bankSetup.page=0;bankRender();return;}
 if(a==='confirm-start'){bankStartPending();return;}
 if(a==='practice'){bankPracticeStart();return;}
 if(a==='previous'||a==='next'){state.bankSetup.page+=a==='next'?1:-1;const el=view.querySelector('#sb-results');if(el)el.innerHTML=bankResults();}
});
view.addEventListener('change',e=>{
 if(state.game!=='study-bank')return;const el=e.target;
 if(['sb-scope','sb-topic','sb-level','sb-type','sb-origin'].includes(el.id)){state.bankSetup[el.id.slice(3)]=el.value;state.bankSetup.page=0;bankRender();}
});
view.addEventListener('input',e=>{
 if(state.game!=='study-bank'||e.target.id!=='sb-query')return;
 state.bankSetup.query=e.target.value;state.bankSetup.page=0;const el=view.querySelector('#sb-results');if(el)el.innerHTML=bankResults();const count=view.querySelector('#sb-practice-count');if(count)count.textContent=bankFiltered().length+' câu phù hợp · Mỗi lượt tối đa 10 câu';const start=view.querySelector('#sb-practice-start');if(start)start.disabled=!bankFiltered().length;
});

/* Compatibility for saved 2.12 links and attempts. All actions use the shared bank. */
function collectionOpen(){
 const a=state.reviewSession;
 state.bankSetup={...bankDefault(),mode:'practice',subject:a?.source==='collection'?a.subject:'chemistry',grade:a?.source==='collection'?a.grade:'7',scope:a?.source==='collection'&&a.scope!=='all'?a.scope:'year'};
 bankOpen();
}


